"""Generate CSS tokens and a standalone visual specification from the same JSON."""
from pathlib import Path
import json
import html

root=Path(__file__).resolve().parent
data=json.loads((root/'design-tokens.json').read_text(encoding='utf-8'))
base={
    'font-ui':data['fontFamilies']['ui'], 'font-mono':data['fontFamilies']['mono'],
    'paper-size':'17px', 'reading-scale':'1'
}
for name,value in data['fontWeights'].items():base['weight-'+name]=str(value)
for role,values in data['typography'].items():
    for key,unit in [('size','px'),('lineHeight','px'),('weight','')]:
        base['type-'+role+'-'+{'lineHeight':'line'}.get(key,key)]=str(values[key])+unit
for name,value in data['spacing'].items():base['space-'+name]=str(value)+'px'
for name,value in data['radii'].items():base['radius-'+name]=str(value)+'px'
for name,values in data['components'].items():
    for key,value in values.items():
        key=''.join('-'+c.lower() if c.isupper() else c for c in key)
        base[name+'-'+key]=str(value)+'px'
for name,value in data['layout'].items():
    name=''.join('-'+c.lower() if c.isupper() else c for c in name)
    base['layout-'+name]=str(value)+'px'
base.update({'motion-feedback':str(data['motion']['feedback'])+'ms','motion-drawer':str(data['motion']['drawer'])+'ms','motion-easing':data['motion']['easing']})
def block(selector,values):return selector+' {\n'+''.join('  --'+k+': '+v+';\n' for k,v in values.items())+'}\n'
css='/* Generated by build-design-system.py. Edit design-tokens.json. */\n'
css+=block(':root',base)
for name,theme in data['themes'].items():
    values={k:v for k,v in theme.items() if k!='label'}
    css+=block(':root' if name=='light' else ':root[data-theme="'+name+'"]',values)
(root/'design-tokens.css').write_text(css,encoding='utf-8')

typography=''.join(f'<tr><td>{html.escape(v["label"])}</td><td class="sample" style="font-family:var(--font-{v.get("family","ui")});font-size:{v["size"]}px;line-height:{v["lineHeight"]}px;font-weight:{v["weight"]}">{html.escape(v["sample"])}</td><td>{v["size"]} / {v["lineHeight"]} px</td><td>{v["weight"]}</td></tr>' for v in data['typography'].values())
component_names={'button':'文字按钮','icon-button':'图标按钮','format-button':'格式工具按钮','input':'输入框','search':'搜索框','navigation':'导航项','document-row':'文档列表项','segment':'分段选择器','checkbox':'复选框','table':'表格'}
dimension_names={'height':'高度','paddingX':'水平内边距','paddingY':'垂直内边距','gap':'图文间距','iconSize':'图标','size':'尺寸','hitArea':'点击区域','rowHeight':'行高','mobileHeight':'高度','mobileSize':'尺寸','mobileHitArea':'点击区域'}
components=''.join('<tr><td>'+component_names[name]+'</td><td>'+ '，'.join(dimension_names.get(key,key)+' '+str(value)+'px' for key,value in values.items() if not key.startswith('mobile'))+'</td><td>'+ '，'.join(dimension_names.get(key,key)+' '+str(value)+'px' for key,value in values.items() if key.startswith('mobile'))+'</td></tr>' for name,values in data['components'].items())
colors=''.join('<div class="color"><i style="background:'+value+'"></i><span>'+key+'<small>'+value+'</small></span></div>' for key,value in data['themes']['light'].items() if key in ['text','secondary','bg','canvas','accent','accent-soft','line','success','danger'])
rules=''.join('<li>'+html.escape(rule)+'</li>' for rule in data['rules'])
page='''<!doctype html><html lang="zh-CN"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>笺墨 · 字体与组件设计规范 v3</title><style>
TOKENS
*{box-sizing:border-box}body{margin:0;background:var(--canvas);color:var(--text);font:13px/1.7 var(--font-ui)}button,input{font-family:inherit}a{color:var(--accent);text-underline-offset:4px}button:focus-visible,a:focus-visible{outline:2px solid var(--focus);outline-offset:2px}.doc{max-width:1180px;margin:auto;padding:48px 40px 64px}.doc-head{display:flex;align-items:flex-start;justify-content:space-between;gap:24px;margin-bottom:36px}.doc-head h1{font-size:28px;line-height:40px;font-weight:600;margin:6px 0 12px}.doc-head p{color:var(--secondary);margin:0}.version{font-size:12px;color:var(--secondary)}.back{display:block;padding:9px 15px;border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--text);text-decoration:none;white-space:nowrap}.toc{display:flex;gap:24px;border-bottom:1px solid var(--line);padding:0 0 16px;margin-bottom:36px;flex-wrap:wrap}.toc a{text-decoration:none;font-weight:500}.section{background:var(--bg);border:1px solid var(--line);border-radius:10px;padding:28px 32px;margin-top:24px;scroll-margin-top:24px}.section h2{font-size:20px;line-height:30px;font-weight:600;margin:0 0 12px}.section>p{color:var(--secondary);margin:0 0 24px}.table-wrap{overflow:auto}table{width:100%;border-collapse:collapse;text-align:left}th{font-size:12px;font-weight:500;background:var(--source);color:var(--secondary)}th,td{padding:16px;border-bottom:1px solid var(--line);vertical-align:middle}td:first-child{min-width:155px;color:var(--secondary)}td:nth-last-child(-n+2){white-space:nowrap;font-variant-numeric:tabular-nums;font-size:12px;color:var(--secondary)}.sample{min-width:320px;color:var(--text)}.type-note{padding:16px;background:var(--source);border-radius:6px;color:var(--secondary);margin:24px 0 0;font-size:12px}.component-demo{display:flex;align-items:center;gap:16px;flex-wrap:wrap;padding:28px 0;margin-bottom:8px}.spec-button{height:var(--button-height);padding:0 var(--button-padding-x);border-radius:var(--radius-control);font-size:var(--type-button-size);line-height:var(--type-button-line);font-weight:var(--type-button-weight);display:inline-flex;align-items:center;gap:var(--button-gap);border:1px solid transparent;cursor:pointer;background:var(--accent);color:var(--accent-ink);transition:background var(--motion-feedback)}.spec-button:hover,.spec-button.is-hover{background:var(--accent-hover)}.spec-button:active,.spec-button.is-pressed{background:var(--accent-pressed)}.spec-button.is-focus{outline:2px solid var(--focus);outline-offset:2px}.spec-button.secondary{border-color:var(--line);background:var(--bg);color:var(--text)}.spec-button:disabled{background:var(--disabled-bg);color:var(--disabled-text);cursor:not-allowed}.spec-button svg{width:16px;height:16px;stroke:currentColor;fill:none;stroke-width:1.5}.state{display:flex;flex-direction:column;gap:12px;align-items:flex-start}.state>span{font-size:12px;color:var(--secondary)}.spec-input{height:var(--input-height);padding:0 var(--input-padding-x);border:1px solid var(--line);border-radius:var(--radius-control);background:var(--bg);font-size:13px;color:var(--text);max-width:220px}.spec-input:focus{outline:2px solid var(--focus);outline-offset:2px}.themes{display:flex;gap:8px;flex-wrap:wrap}.themes button{border:1px solid var(--line);border-radius:6px;background:var(--bg);color:var(--secondary);font-size:12px;padding:6px 12px;cursor:pointer}.themes button.active{background:var(--accent-soft);color:var(--accent);border-color:var(--accent)}.colors{display:grid;grid-template-columns:repeat(3,1fr);gap:20px;margin:24px 0}.color{display:flex;gap:12px;align-items:center}.color i{width:40px;height:40px;border:1px solid var(--line);border-radius:8px;flex-shrink:0}.color span{font-size:12px;font-weight:500}.color small{display:block;font-size:12px;font-weight:400;color:var(--secondary);font-family:var(--font-mono)}.spacing{display:flex;gap:18px;align-items:flex-end;flex-wrap:wrap;margin-top:24px}.space-item span{display:block;background:var(--accent-soft);border-left:2px solid var(--accent);height:24px;margin-bottom:8px}.space-item small{font-size:12px;color:var(--secondary)}.layout{display:grid;grid-template-columns:1fr 2.8fr 1fr;border:1px solid var(--line);border-radius:8px;overflow:hidden;margin:24px 0}.layout div{padding:24px 16px;border-right:1px solid var(--line);background:var(--source);min-height:150px;font-size:13px}.layout div:nth-child(2){background:var(--bg)}.layout div:last-child{border-right:0}.layout small{display:block;color:var(--secondary);font-size:12px;line-height:2;margin-top:12px}.rules{padding-left:20px;margin:20px 0 0}.rules li{padding-left:4px;margin:10px 0;color:var(--secondary)}.notice{border-left:2px solid var(--accent);padding:12px 16px;background:var(--source);font-size:12px;color:var(--secondary);margin-top:24px}footer{display:flex;justify-content:space-between;gap:24px;padding-top:32px;font-size:12px;color:var(--secondary)}@media(max-width:760px){.doc{padding:28px 20px}.doc-head{flex-direction:column}.doc-head h1{font-size:25px}.section{padding:24px 20px}.colors{grid-template-columns:1fr 1fr}.spec-button{height:44px;min-width:44px}.spec-input{height:44px;font-size:var(--type-mobile-input-size)}.themes button{min-height:44px}.layout{grid-template-columns:1fr}.layout div{min-height:100px;border-right:0;border-bottom:1px solid var(--line)}.toc{gap:16px}th,td{padding:12px}.component-demo{gap:20px}footer{flex-direction:column}}@media(prefers-reduced-motion:reduce){*{transition:none!important;scroll-behavior:auto!important}}
</style></head><body><main class="doc"><header class="doc-head"><div><span class="version">笺墨设计规范 · v3.0</span><h1>字体、控件与布局，都有明确的尺度。</h1><p>规范与实际界面共享 design-tokens.json，修改规则后统一生成。</p></div><a class="back" href="design-review.html">查看新版界面</a></header><nav class="toc" aria-label="规范目录"><a href="#type">字体与字重</a><a href="#controls">按钮与输入</a><a href="#color">颜色与状态</a><a href="#space">间距与布局</a><a href="#rules">执行与验收</a></nav>
<section class="section" id="type"><h2>字体与字重</h2><p>界面只保留 12 / 13px 两档常用文字，文章建立独立层级。字重限定为 400 / 500 / 600。</p><div class="table-wrap"><table><thead><tr><th>使用位置</th><th>实际字样</th><th>字号 / 行高</th><th>字重</th></tr></thead><tbody>TYPOGRAPHY</tbody></table></div><div class="type-note">macOS 使用 SF / 苹方，Windows 使用 Segoe UI / 微软雅黑；代码使用 SF Mono / Consolas。系统字形可能不同，字号、行高和层级统一。正文 17px 是默认值，字号偏好只缩放文稿，不缩放工具栏。</div></section>
<section class="section" id="controls"><h2>按钮与输入</h2><p>桌面文字按钮 32px 高，图标按钮 28px；手机可点击目标至少 44 × 44px。按钮文字固定 13px / 500。</p><div class="component-demo"><div class="state"><button class="spec-button">编辑文档</button><span>默认</span></div><div class="state"><button class="spec-button is-hover">编辑文档</button><span>悬停</span></div><div class="state"><button class="spec-button is-pressed">编辑文档</button><span>按下</span></div><div class="state"><button class="spec-button is-focus">编辑文档</button><span>键盘焦点</span></div><div class="state"><button class="spec-button" disabled>编辑文档</button><span>禁用</span></div><div class="state"><button class="spec-button secondary">导出文档</button><span>次要操作</span></div></div><div class="component-demo"><label for="example-input">文档名称</label><input id="example-input" name="example-title" class="spec-input" placeholder="例如：阅读笔记…" autocomplete="off"><span class="version">40px 高 / 12px 水平内边距 / 6px 圆角</span></div><div class="table-wrap"><table><thead><tr><th>组件</th><th>桌面尺寸</th><th>手机尺寸</th></tr></thead><tbody>COMPONENTS</tbody></table></div><div class="notice">异步加载时：保持原有按钮宽度和高度，使用 16px 加载图标、显示具体动作名称，并在请求期间禁用重复提交。本地同步操作不添加模拟加载。</div></section>
<section class="section" id="color"><h2>颜色与状态</h2><p>颜色表达内容层级和交互状态；选中、焦点同时用形状、描边或位置标记。</p><div class="themes" role="group" aria-label="规范示例主题"><button data-theme="light" class="active" aria-pressed="true">晴昼</button><button data-theme="warm" aria-pressed="false">纸页</button><button data-theme="dark" aria-pressed="false">深夜</button></div><div class="colors" id="colors">COLORS</div><p class="type-note">标准文字与实际底色的对比度至少 4.5:1。hover / pressed / focus / disabled 均有独立 token。操作成功和错误使用语义色；禁用控件不与可用状态混淆。</p></section>
<section class="section" id="space"><h2>间距与布局</h2><p>4px 基础网格。紧邻的图标与文字相隔 6px；相关控件 8px；区域内 16–24px；区域之间 32px。</p><div class="spacing">SPACING</div><div class="layout"><div>文档库<small>宽 248px<br>列表项高 56px<br>左右内边距 16px</small></div><div>文稿优先的工作区<small>顶栏 60px / 标签 40px / 工具区 48px<br>纸面最大宽 848px；左右内边距 56px<br>默认单文稿；源码与分栏按需切换</small></div><div>大纲<small>宽 208px<br>行高至少 32px<br>窄屏以弹窗打开</small></div></div><p class="type-note">≤1320px 收起常驻大纲；≤760px 使用手机布局。手机正文两侧各 24px，标题 28px / 40px，底部操作栏 64px + 安全区，工具栏在编辑时横向滚动。</p></section>
<section class="section" id="rules"><h2>执行与验收</h2><p>以下规则直接约束实际 CSS 和组件实现，不只用于视觉说明。</p><ul class="rules">RULES</ul><div class="notice">当前检查包含规范与 CSS token 一致性、字重与字号约束、对比度、语义标签和交互逻辑。真实浏览器截图、触屏与输入法体验需要单独验收，不能以静态检查代替。</div></section><footer><span>来源：design-tokens.json · 单一规则源</span><a href="jianmo-preview.html">打开编辑器</a></footer></main>
<script>const designData=DATA;document.querySelectorAll('[data-theme]').forEach(button=>button.addEventListener('click',()=>{const theme=button.dataset.theme;document.documentElement.dataset.theme=theme;document.documentElement.style.colorScheme=theme==='dark'?'dark':'light';document.querySelectorAll('[data-theme]').forEach(b=>{b.classList.toggle('active',b===button);b.setAttribute('aria-pressed',String(b===button));});const colors=document.getElementById('colors');colors.replaceChildren();for(const key of ['text','secondary','bg','canvas','accent','accent-soft','line','success','danger']){const item=document.createElement('div');item.className='color';const swatch=document.createElement('i');swatch.style.background=designData.themes[theme][key];const label=document.createElement('span');label.textContent=key;const hex=document.createElement('small');hex.textContent=designData.themes[theme][key];label.append(hex);item.append(swatch,label);colors.append(item);}}));</script></body></html>'''
spacing=''.join(f'<div class="space-item"><span style="width:{value}px"></span><small>{value}px</small></div>' for value in data['spacing'].values())
for key,value in [('TOKENS',css),('TYPOGRAPHY',typography),('COMPONENTS',components),('COLORS',colors),('SPACING',spacing),('RULES',rules),('DATA',json.dumps(data,ensure_ascii=False).replace('</','<\\/'))]:
    page=page.replace(key,value)
(root/'design-system.html').write_text(page,encoding='utf-8')
print('Generated design-tokens.css and design-system.html from design-tokens.json')
